 $('action-settings').innerHTML=html;$('run-image-action').textContent=a==='segment'||a==='segment_sam3'?'识别并显示选区':actionNames[a];$('image-error').hidden=true;
 const allowed=new Set(['move',...config.modes.filter(([v])=>['point','box','brush'].includes(v)).map(([v])=>v)]);document.querySelectorAll('[data-mode]').forEach(b=>b.disabled=!allowed.has(b.dataset.mode));
 if(changedTool){selectionMethod=config.default;if(['point','box','brush'].includes(config.default))setMode(config.default,true);else{mode='move';document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x.dataset.mode==='move'));if(config.default!=='mask')resetSelection();}}
 $('action-settings').querySelectorAll('[data-selection-mode]').forEach(b=>b.onclick=()=>{selectionChangedAt=Date.now()/1000;const value=b.dataset.selectionMode;if(['point','box','brush'].includes(value))setMode(value,true);else{selectionMethod=value;mode='move';document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x.dataset.mode==='move'));document.querySelectorAll('[data-selection-mode]').forEach(x=>x.classList.toggle('selected',x===b));if(value==='text')resetSelection();else drawSelection();}});
 if($('sam3-prompt'))$('sam3-prompt').oninput=()=>{selectionChangedAt=Date.now()/1000;maskPreview=null;drawSelection();};drawSelection();
