function sourceBox(box){const l=layer(),a=asset(l.asset);return {x:l.x+box[0]/a.width*l.width,y:l.y+box[1]/a.height*l.height,w:box[2]/a.width*l.width,h:box[3]/a.height*l.height};}
function applyImageDemo(){
 const demo=project.draft.demo;if(!demo||document.body.dataset.demoReady)return;document.body.dataset.demoReady='true';
 const action=DEMO_ACTIONS[demo];
 if(action){
  $('image-action').value=action;actionSettings();document.querySelector('[data-inspector="ai"]').click();
  $('image-action').closest('label').hidden=true;document.body.classList.add('demo-image-action');
  document.querySelectorAll('[data-mode]').forEach(button=>button.hidden=button.disabled);
  if(['image-select','image-local'].includes(demo)){setMode('box',true);selection=sourceBox([110,50,200,170]);}
  if(['image-erase','image-replace-text'].includes(demo)){setMode('box',true);selection=sourceBox([26,13,123,38]);}
  if(demo==='image-perspective'){setMode('point',true);const l=layer(),a=asset(l.asset);points=[[130,55],[540,95],[500,360],[85,320]].map(([x,y])=>({x:l.x+x/a.width*l.width,y:l.y+y/a.height*l.height}));}
  if(demo==='image-sam3-zim')$('sam3-prompt').value='coffee cup';
  if(demo==='image-mask-refine'){$('mask-grow').value=2;$('mask-feather').value=2;}
  if(demo==='image-auto-adjust'){$('adj-white').checked=true;$('adj-levels').checked=true;$('adj-gamma').value=1.1;$('adj-sharpen').value=.4;}
  if(demo==='image-color-match')$('match-reference').value=project.assets.find(a=>a.kind==='image'&&a.id!==layer().asset)?.id||'';
  if(demo==='image-product-layout'){$('product-width').value=600;$('product-height').value=600;$('product-margin').value=70;$('product-shadow').value=18;}
  if(demo==='image-watermark-batch'){document.querySelectorAll('[data-batch-image]').forEach(x=>x.checked=true);$('batch-width').value=600;$('batch-height').value=600;$('batch-watermark').value='UPDREAM';}
  if(demo==='image-replace-text'){$('replace-text').value='夏日新品';$('replace-size').value=24;}
  drawSelection();return;
 }
 if(!CANVAS_DEMOS.has(demo)||doc.revision||doc.layers.length!==1)return;
 document.body.classList.add('demo-canvas-action');
 document.querySelector('[data-inspector="ai"]').hidden=true;
 const base=layer();
 if(demo==='image-adjustment-layers'){const l=newLayer('adjustment',{name:'暖调调整',width:doc.width,height:doc.height,contrast:1.18,saturation:.72,temperature:.25,gamma:1.08,opacity:.9});doc.layers.push(l);selectLayer(l.id);}
 if(demo==='image-text-effects'){const l=newLayer('text',{name:'标题',text:'自动换行标题示例',x:30,y:40,width:Math.max(100,doc.width-60),height:160,size:52,color:'#ffffff',stroke_color:'#000000',stroke_width:3,shadow_color:'#000000',shadow_blur:4,shadow_x:3,shadow_y:4,text_align:'center'});doc.layers.push(l);selectLayer(l.id);}
 if(demo==='image-layout-guides'&&base){doc.width=720;doc.height=300;doc.background='#f1f4ed';base.x=40;base.y=70;base.width=180;base.height=120;base.name='杯子 1';for(let i=1;i<3;i++)doc.layers.push(newLayer('image',{asset:base.asset,name:`杯子 ${i+1}`,x:40+i*230,y:70,width:180,height:120}));selectLayer(doc.layers.at(-1).id);}
 changed();
}
$('image-action').onchange=()=>{selectionChangedAt=Date.now()/1000;actionSettings();};document.querySelectorAll('[data-inspector]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-inspector]').forEach(x=>x.classList.toggle('selected',x===b));$('properties-panel').hidden=b.dataset.inspector!=='properties';$('ai-panel').hidden=b.dataset.inspector!=='ai';});
function sourceSelection(l){const a=asset(l.asset),sx=a.width/l.width,sy=a.height/l.height;if(selection){const p1=transformPoint(selection.x,selection.y,l,true),p2=transformPoint(selection.x+selection.w,selection.y+selection.h,l,true);const x=Math.max(0,Math.floor(Math.min(p1.x,p2.x)*sx)),y=Math.max(0,Math.floor(Math.min(p1.y,p2.y)*sy));return {box:[x,y,Math.min(a.width-x,Math.ceil(Math.abs(p2.x-p1.x)*sx)),Math.min(a.height-y,Math.ceil(Math.abs(p2.y-p1.y)*sy))]};}return {points:points.map(p=>{const s=transformPoint(p.x,p.y,l,true);return [Math.round(s.x*sx),Math.round(s.y*sy)];})};}
async function brushMask(l){const a=asset(l.asset);const c=document.createElement('canvas');c.width=a.width;c.height=a.height;const t=c.getContext('2d');t.fillStyle='black';t.fillRect(0,0,c.width,c.height);t.strokeStyle='white';t.lineCap='round';t.lineJoin='round';for(const stroke of brushes){t.lineWidth=stroke.size*a.width/l.width;t.beginPath();stroke.points.forEach((p,i)=>{const s=transformPoint(p.x,p.y,l,true);const x=s.x*a.width/l.width,y=s.y*a.height/l.height;i?t.lineTo(x,y):t.moveTo(x,y);});t.stroke();}const blob=await new Promise(r=>c.toBlob(r,'image/png'));const data=new FormData();data.append('file',blob,'selection-mask.png');const res=await fetch(href(path('/assets')),{method:'POST',body:data});if(!res.ok)throw Error(errorText(await res.json().catch(()=>({detail:'无法保存选区'})),res.status,res.headers.get('X-Request-ID')));return (await res.json()).id;}
async function showMaskArtifact(job,layerId,fresh=false){overlay.dataset.maskState='loading';const artifact=job.artifacts.find(a=>a.name==='mask.png');if(!artifact){overlay.dataset.maskState='missing';return false;}const image=new Image();image.src=href(artifact.url);await image.decode();if(!fresh){selection=null;points=[];brushes=[];}maskPreview={job:job.id,layer:layerId,image};maskOverlayVisible=true;latestJob=null;overlay.dataset.maskState='shown';drawSelection();if(fresh)toast('主体选区已显示在画布上');return true;}
async function waitForSubmittedMask(meta){const deadline=Date.now()+300000,url=path(`/jobs/${meta.id}/files/mask.png`);overlay.dataset.maskState='waiting';while(Date.now()<deadline){if(maskPreview?.job===meta.id)return;const response=await fetch(href(url),{credentials:'same-origin',cache:'no-store'});overlay.dataset.maskState=String(response.status);if(response.ok){const job={id:meta.id,artifacts:[{name:'mask.png',url:url+'?preview='+Date.now()}]};if(!(await showMaskArtifact(job,meta.layer,true)))throw Error('主体选择完成，但没有生成蒙版文件');return;}if(response.status!==404)throw Error(`无法读取主体蒙版（${response.status}）`);const state=await api(path('')),job=state.jobs.find(x=>x.id===meta.id);if(job&&['failed','cancelled'].includes(job.status))throw Error(job.error||'主体选择任务未完成');await new Promise(resolve=>setTimeout(resolve,1200));}throw Error('主体选择等待超时，请在任务记录中查看状态');}
async function submit(task){const r=await api(path('/image-jobs'),{method:'POST',body:JSON.stringify(task)});latestJob={id:r.id,action:task.action,layer:selected};overlay.dataset.maskState='submitted';if(['segment','segment_sam3'].includes(task.action)){maskPreview=null;drawSelection();toast('正在识别主体，完成后会直接显示选区');await refresh();await waitForSubmittedMask({id:r.id,action:task.action,layer:selected});}else{toast('已提交，结果会显示在画布下方');await refresh();}}
$('export-document').onclick=async()=>{try{await submit({action:'export',document:doc,format:$('export-format').value});}catch(e){toast(e.message,true);}};
$('run-image-action').onclick=async()=>{if(busy)return;busy=true;$('run-image-action').disabled=true;try{const action=$('image-action').value,l=layer();if(action!=='batch_export'&&(!l||l.kind!=='image'))throw Error('请先选择一个图片图层');const task={action,asset:l?.asset};
 if(action==='batch_export'){const assets=[...document.querySelectorAll('[data-batch-image]:checked')].map(x=>x.value);if(!assets.length)throw Error('请选择至少一张图片');const r=await api(path('/image-batch'),{method:'POST',body:JSON.stringify({assets,width:+$('batch-width').value,height:+$('batch-height').value,background:$('batch-background').value,format:$('batch-format').value,watermark:$('batch-watermark').value})});toast(`已提交 ${r.jobs.length} 个批处理任务`);await refresh();return;}
 if(['segment','segment_sam3','local_edit','erase','replace_text','perspective'].includes(action)){if(l.rotation!==0)throw Error('选区操作请先将图层旋转恢复为0，或导出并重新载入图片');Object.assign(task,sourceSelection(l));if(brushes.length)task.mask=await brushMask(l);else if(maskAsset)task.mask=maskAsset;}
 if(action==='segment_sam3'){if(brushes.length)throw Error('SAM3 请使用文字、点或框；涂抹蒙版可直接用 ZIM 精修');task.prompt=selectionMethod==='text'?$('sam3-prompt').value:'';task.parameters={confidence:+$('sam3-confidence').value,refine:$('sam3-refine').checked};}
 if(action==='refine_zim'){if(!maskAsset)throw Error('请先把 mask.png 载入为当前选区');task.mask=maskAsset;}
 if(action==='refine_mask'){task.asset=maskAsset||l.asset;task.parameters={grow:+$('mask-grow').value,feather:+$('mask-feather').value,threshold:+$('mask-threshold').value,remove_small:+$('mask-small').value,fill_holes:$('mask-holes').checked};}
 if(action==='local_adjust')task.parameters={brightness:+$('adj-brightness').value,contrast:+$('adj-contrast').value,saturation:+$('adj-saturation').value,temperature:+$('adj-temperature').value,gamma:+$('adj-gamma').value,black_point:+$('adj-black').value,white_point:+$('adj-white-point').value,sharpen:+$('adj-sharpen').value,blur:+$('adj-blur').value,auto_white_balance:$('adj-white').checked,auto_levels:$('adj-levels').checked};
 if(action==='color_match'){task.references=[$('match-reference').value].filter(Boolean);task.parameters={strength:+$('match-strength').value};}
 if(action==='product_layout')task.parameters={width:+$('product-width').value,height:+$('product-height').value,background:$('product-background').value,margin:+$('product-margin').value,shadow:true,shadow_blur:+$('product-shadow').value};
 if($('image-prompt'))task.prompt=$('image-prompt').value;if($('image-quality'))task.quality=$('image-quality').value;if($('image-layer-count'))task.layer_count=+$('image-layer-count').value;
 if($('image-references'))task.references=[...$('image-references').selectedOptions].map(x=>x.value).slice(0,2);
 if(action==='replace_text'){task.text=$('replace-text').value;task.size=+$('replace-size').value;task.color=$('replace-color').value;}
 await submit(task);
 }catch(e){$('image-error').textContent=e.message;$('image-error').hidden=false;}finally{busy=false;$('run-image-action').disabled=false;}};
let renderedJobs='';
async function updateMaskPreview(jobs){
 let job,layerId,fresh=false;
 if(latestJob){job=jobs.find(x=>x.id===latestJob.id);if(!job||activeStatus(job.status))return;if(job.status!=='succeeded'||!['segment','segment_sam3'].includes(latestJob.action)){latestJob=null;return;}layerId=latestJob.layer;fresh=true;}
 else{const l=layer();if(!l||maskAsset)return;job=jobs.find(x=>['segment','segment_sam3'].includes(x.tool)&&x.status==='succeeded'&&x.source_asset===l.asset&&x.created>=selectionChangedAt&&x.artifacts.some(a=>a.name==='mask.png'));if(!job||maskPreview?.job===job.id)return;layerId=l.id;}
 try{if(fresh&&latestJob?.id!==job.id)return;await showMaskArtifact(job,layerId,fresh);}catch{latestJob=null;if(fresh)toast('选区已经生成，但暂时无法覆盖到画布上',true);}
}
async function refresh(){try{const [next,conversation,canvasState]=await Promise.all([api(path('')),api(path('/agent')),api(path('/image-document'))]);project=next;assetList();await loadAssets();if(canvasState.document.revision>doc.revision){serverRevision=canvasState.document.revision;$('canvas-update').hidden=false;$('reload-canvas').textContent=dirty?'备份草稿并载入最新版本':'载入最新版本';$('canvas-update').querySelector('span').textContent=`画布已有版本 ${serverRevision}${dirty?'；本页有未保存编辑，请先保存草稿或导出后再载入。':'，可载入查看 Agent 或其他页面的修改。'}`;}const jobs=project.jobs.filter(j=>j.kind==='image');const active=jobs.filter(j=>activeStatus(j.status));$('image-job-status').textContent=active.length?`${active.length} 个任务处理中`:'结果按完成任务展示';
 await updateMaskPreview(jobs);
 $('image-job-list').innerHTML=jobs.slice(0,8).map(j=>`<div class="image-job ${j.status==='failed'?'error':''}"><span>${actionNames[j.tool]||'图片处理'} · ${jobPhaseLabel(j)}</span>${j.error?`<small>${esc(j.error.slice(0,220))}</small>`:''}${activeStatus(j.status)?`<button class="button text" data-cancel="${j.id}">停止</button>`:''}<button class="button text" data-log="${j.id}">进度</button></div>`).join('');
 $('image-job-list').querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{await api(path(`/jobs/${b.dataset.cancel}/cancel`),{method:'POST'});refresh();});
 $('image-job-list').querySelectorAll('[data-log]').forEach(b=>{const usage=document.createElement('button');usage.type='button';usage.className='button text';usage.dataset.usageJob=b.dataset.log;usage.textContent='消耗';b.after(usage);});bindJobUsage($('image-job-list'),id);
 $('image-job-list').querySelectorAll('[data-log]').forEach(b=>b.onclick=async()=>{const {showText}=await import('./common.js');const r=await api(path(`/jobs/${b.dataset.log}/log`));showText('处理进度',r.text);});
 const agentResults=conversation.turns.filter(t=>t.status==='succeeded'&&t.artifacts.some(a=>/\.(png|jpe?g|webp)$/i.test(a.name))).map(t=>({...t,tool:'agent',isAgent:true}));
 const done=[...jobs.filter(j=>j.status==='succeeded'),...agentResults].sort((a,b)=>b.created-a.created);resultGroups=done;$('compare-candidates').hidden=!done.some(j=>j.artifacts.some(a=>eligibleCandidate(a.name)));const sig=done.map(j=>j.id).join('|');if(sig!==renderedJobs){renderedJobs=sig;$('image-output').innerHTML=done.map((j,n)=>{const rows=j.artifacts.filter(a=>/\.(png|jpe?g|webp)$/i.test(a.name)||/\.(psd|ora|zip)$/.test(a.name));return `<${n?'details':'section'}>${n?`<summary>${actionNames[j.tool]||'Agent 图片'} · ${date(j.created)}</summary>`:''}${j.tool==='decompose'?`<button class="button primary wide" data-import-layers="${j.id}">载入全部分层结果</button>`:''}${j.tool==='ocr'?`<button class="button secondary wide" data-ocr="${j.id}">查看识别文字</button>`:''}${rows.map(a=>`<div class="image-result">${/\.(png|jpe?g|webp)$/i.test(a.name)?`<img src="${href(a.url)}" alt="">`:''}<div><strong>${esc(a.name)}</strong><div class="result-actions">${/\.(png|jpe?g|webp)$/i.test(a.name)?`<button class="button text" data-preview="${a.url}">预览</button><button class="button text" data-import="${j.id}" data-origin="${j.isAgent?'agent':'job'}" data-name="${esc(a.name)}">${a.name==='mask.png'?'用作选区':'载入图层'}</button>`:''}<a href="${href(a.url+'?download=true')}" download>下载</a></div></div></div>`).join('')}</${n?'details':'section'}>`;}).join('');
 const lookup=done.flatMap(j=>j.artifacts);$('image-output').querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>openMedia(lookup.find(a=>a.url===b.dataset.preview)));
 $('image-output').querySelectorAll('[data-import]').forEach(b=>b.onclick=()=>importJob(b.dataset.import,[b.dataset.name],b.dataset.name.endsWith('mask.png'),false,b.dataset.origin==='agent'));
 $('image-output').querySelectorAll('[data-import-layers]').forEach(b=>b.onclick=()=>{const j=done.find(j=>j.id===b.dataset.importLayers);importJob(j.id,j.artifacts.filter(a=>/^layer-\d+\.png$/.test(a.name)).map(a=>a.name),false,true);});
 $('image-output').querySelectorAll('[data-ocr]').forEach(b=>b.onclick=async()=>{const j=done.find(j=>j.id===b.dataset.ocr),a=j.artifacts.find(a=>a.name==='ocr.json');const data=await(await fetch(href(a.url))).json();$('ocr-lines').innerHTML=data.lines.map((l,i)=>`<button class="ocr-line" data-line="${i}">${esc(l.text)} <small>${Math.round(l.confidence*100)}%</small></button>`).join('')||'<p class="image-hint">没有识别到清晰文字。</p>';document.querySelector('[data-inspector="ai"]').click();$('ocr-lines').querySelectorAll('button').forEach(btn=>btn.onclick=()=>{const target=doc.layers.find(l=>l.asset===j.source_asset);if(target)selectLayer(target.id);const l=layer();if(!l||l.kind!=='image')return toast('请先选中识别的原图层',true);const row=data.lines[+btn.dataset.line],a=asset(l.asset);const [x,y,w,h]=row.box;selection={x:l.x+x/a.width*l.width,y:l.y+y/a.height*l.height,w:w/a.width*l.width,h:h/a.height*l.height};points=[];brushes=[];maskAsset=null;maskPreview=null;$('image-action').value='replace_text';actionSettings();$('replace-text').value=row.text;$('replace-size').value=Math.max(8,Math.min(300,Math.round(h*.85)));drawSelection();});});}
 }catch(e){toast(e.message,true);}finally{clearTimeout(pollTimer);pollTimer=setTimeout(refresh,3000);}}
async function importJob(job,names,mask=false,all=false,isAgent=false){try{if(!names.length)throw Error('没有可载入图层');const r=await api(path('/image-import'),{method:'POST',body:JSON.stringify({[isAgent?'turn':'job']:job,names})});project=await api(path(''));await loadAssets();assetList();if(mask){maskAsset=r.assets[0].id;maskPreview=null;drawSelection();toast('蒙版已作为当前选区并显示在画布上');return;}
 if(all){if(doc.layers.some(l=>l.locked))throw Error('请先解锁现有图层，再整体载入分层结果');remember();const a=r.assets[0];doc.width=a.width;doc.height=a.height;doc.background='transparent';doc.layers=[];for(const result of r.assets)doc.layers.push(newLayer('image',{asset:result.id,name:result.name,width:a.width,height:a.height}));selected=doc.layers.at(-1).id;properties();changed();}
 else{if(names.some(n=>n.endsWith('foreground.png'))&&layer()&&!layer().locked){remember();layer().visible=false;}for(const a of r.assets)addAsset(asset(a.id));}
 }catch(e){toast(e.message,true);}}
function versionLabel(c={}){return ({agent:'Agent 修改',manual:'手动保存',candidate:'应用候选',lock:'锁定图层',unlock:'解锁图层'})[c.kind]?(c.name?c.name+' · ':'')+({agent:'Agent 修改',manual:'手动保存',candidate:'应用候选',lock:'锁定图层',unlock:'解锁图层'})[c.kind]:'';}
function canRestore(next){for(const l of doc.layers.filter(x=>x.locked)){const n=next.layers.find(x=>x.id===l.id);if(!n||Object.keys(l).some(k=>(k==='locked'?!!n[k]:n[k])!==(k==='locked'?!!l[k]:l[k]))||doc.layers.some((other,i)=>{const j=next.layers.findIndex(x=>x.id===other.id);return j>=0&&(i<doc.layers.indexOf(l))!==(j<next.layers.indexOf(n));})){toast('旧状态会修改已锁定图层，请先手动解锁：'+l.name,true);return false;}}return true;}
async function acceptDocument(value){doc=value;dirty=false;undo=[];redo=[];if(!doc.layers.some(l=>l.id===selected))selected=null;resetSelection();properties();render();$('canvas-update').hidden=true;$('document-status').textContent='已保存 · 版本 '+doc.revision;await versions();}
async function toggleLock(layerId){await ready;if(saveBusy)return;try{if(dirty&&!(await save()))return;const target=doc.layers.find(l=>l.id===layerId);if(!target)return;document.querySelector('.image-layout').inert=true;const r=await api(path('/image-layer-lock'),{method:'POST',body:JSON.stringify({revision:doc.revision,layer_id:layerId,locked:!target.locked})});await acceptDocument(r.document);toast(target.locked?'图层已解锁':'图层已锁定');}catch(e){toast(e.message,true);}finally{document.querySelector('.image-layout').inert=false;}}
$('edit-selected-chat').onclick=async()=>{await ready;const target=layer();if(!target||target.locked)return;if((dirty||!doc.revision)&&!(await save()))return;await api(path('/draft'),{method:'PUT',body:JSON.stringify({preset:project.draft.preset,prompt:'',editor:'chat'})});location.assign(editorHref('chat',id)+`?layer=${encodeURIComponent(target.id)}&revision=${doc.revision}`);};
$('reload-canvas').onclick=async()=>{try{if(dirty){const blob=new Blob([snapshot()],{type:'application/json'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='canvas-unsaved.json';a.click();URL.revokeObjectURL(url);toast('未保存的画布已下载为草稿');}project=await api(path(''));await loadAssets();await acceptDocument((await api(path('/image-document'))).document);}catch(e){toast(e.message,true);}};
function previewDocument(value){const c=document.createElement('canvas');drawDocument(c,value,images);return c.toDataURL('image/png');}
async function compareVersion(revision){try{const target=await api(path('/image-document/'+revision));const expected=doc.revision;await openCompare({title:'画布版本对比',before:{name:'当前画布',url:previewDocument(doc)},candidates:[{name:'版本 '+revision,url:previewDocument(target)}],onApply:async()=>{if(!canRestore(target))throw Error('请先手动解锁受影响的图层');const r=await api(path('/image-document'),{method:'PUT',body:JSON.stringify({...target,revision:expected})});await acceptDocument({...target,revision:r.revision});toast('已恢复并保存为新版本');}});}catch(e){toast(e.message,true);}}
async function compareSaved(before,after){try{const [a,b]=await Promise.all([api(path('/image-document/'+before)),api(path('/image-document/'+after))]);await openCompare({title:'Agent 修改前后',before:{name:'版本 '+before,url:previewDocument(a)},candidates:[{name:'版本 '+after,url:previewDocument(b)}]});}catch(e){toast(e.message,true);}}
function eligibleCandidate(name){return /\.(png|jpe?g|webp)$/i.test(name)&&!/(^|\/)(mask|before)\.(png|jpe?g|webp)$/i.test(name);}
$('compare-candidates').onclick=async()=>{try{const target=layer();if(!target||target.kind!=='image')throw Error('请先选择要替换的图片图层');if(target.locked)throw Error('请先手动解锁选中的图层');if((dirty||!doc.revision)&&!(await save()))return;const expected=doc.revision,layerId=target.id,comparisonDoc=JSON.parse(snapshot());
 const candidates=resultGroups.flatMap(j=>j.artifacts.filter(a=>eligibleCandidate(a.name)).map(a=>({name:(j.isAgent?'Agent':actionNames[j.tool]||'图片')+' · '+date(j.created)+' · '+a.name,url:href(a.url),artifact:a.name,job:j.id,isAgent:!!j.isAgent,preview:async()=>{const im=new Image();im.src=href(a.url);await im.decode();const map=new Map(images);map.set('__candidate__',im);const next={...comparisonDoc,layers:comparisonDoc.layers.map(l=>l.id===layerId?{...l,asset:'__candidate__'}:l)},c=document.createElement('canvas');drawDocument(c,next,map);return c.toDataURL('image/png');}}))).slice(0,40);
 await openCompare({title:'选择效果 · '+target.name,before:{name:'当前画布',url:previewDocument(comparisonDoc)},candidates,onApply:async choice=>{const imported=await api(path('/image-import'),{method:'POST',body:JSON.stringify({[choice.isAgent?'turn':'job']:choice.job,names:[choice.artifact]})});const r=await api(path('/image-apply'),{method:'POST',body:JSON.stringify({revision:expected,layer_id:layerId,asset:imported.assets[0].id})});project=await api(path(''));await loadAssets();assetList();await acceptDocument(r.document);toast('已应用到原图层，位置与样式保留');}});
 }catch(e){toast(e.message,true);}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});window.addEventListener('pagehide',()=>clearTimeout(pollTimer));
(async()=>{try{project=await api(path(''));header('images',project);$('image-chat-link').href=editorHref('chat',id);document.title=project.name+' · 图片工作台 · updream-AI 编辑';await document.fonts.load('24px UpdreamCJK');await loadAssets();const data=await api(path('/image-document'));doc=data.document;$('document-status').textContent=doc.revision?'已保存 · 版本 '+doc.revision:'画布未保存';assetList();properties();actionSettings();render();await versions();if(!doc.layers.length&&project.assets.some(a=>a.kind==='image'))addAsset(project.assets.find(a=>a.kind==='image'));applyImageDemo();await api(path('/draft'),{method:'PUT',body:JSON.stringify({preset:project.draft.preset,prompt:project.draft.prompt,editor:'images'})});document.querySelectorAll('[data-mode-link],#image-chat-link').forEach(link=>link.onclick=async e=>{if(e.ctrlKey||e.metaKey)return;e.preventDefault();if(dirty&&!(await save()))return;location.assign(link.href);});readyResolve();await refresh();const compare=new URLSearchParams(location.search).get('compare');if(compare&&/^\d+,\d+$/.test(compare)){const [a,b]=compare.split(',').map(Number);await compareSaved(a,b);}else{const initialLayer=new URLSearchParams(location.search).get('layer');if(initialLayer&&doc.layers.some(l=>l.id===initialLayer))selectLayer(initialLayer);}}catch(e){readyResolve();toast(e.message,true);}})();
